def pickle_dump(obj, file_obj=None, protocol=4):
    if file_obj is None:
        file_obj = io.BytesIO()
    pickler = _RestrictedPickler(file_obj, protocol=protocol)
    pickler.dump(obj)
    if isinstance(file_obj, io.BytesIO):
        return file_obj.getvalue()
```

